import React, { useState, useEffect } from 'react';
import './Usuarios.css'; // agregamos estilos personalizados

function Usuarios() {
  const [users, setUsers] = useState([]); // Ahora el estado está vacío inicialmente
  const [search, setSearch] = useState('');
  const [selectedUser, setSelectedUser] = useState(null);
  const [editMode, setEditMode] = useState(false);

  // Efecto para cargar los usuarios cuando el componente se monte
  useEffect(() => {
    const fetchUsers = async () => {
      try {
        const token = localStorage.getItem('token'); // Obtener el token del localStorage o donde lo tengas almacenado

        // Asegúrate de que el token exista antes de hacer la solicitud
        if (!token) {
          console.error('Token no proporcionado');
          return; // Si no hay token, no se hace la solicitud
        }

        const response = await fetch('http://localhost:4000/api/user/allusers', {
          method: 'GET',
          headers: {
            'Authorization': `Bearer ${token}`, // Agregar el token al encabezado
            'Content-Type': 'application/json'
          }
        });

        const data = await response.json();

        // Convertimos los datos a un formato que usamos en el estado
        const transformedUsers = data.map(user => ({
          id: user.id_usuario, // id_usuario -> id
          nombre: user.nombre,
          apellido: user.apellido,
          email: user.email,
          role: user.id_rol === 1 ? 'administrador' : 'usuario' // Convertimos id_rol a un role legible
        }));

        setUsers(transformedUsers); // Actualizamos el estado con los usuarios obtenidos
      } catch (error) {
        console.error('Error fetching users:', error);
      }
    };

    fetchUsers(); // Llamamos la función para cargar los usuarios
  }, []); // El efecto se ejecuta solo una vez cuando el componente se monta

  const filteredUsers = users.filter(user =>
    `${user.nombre} ${user.apellido} ${user.email}`.toLowerCase().includes(search.toLowerCase())
  );

  const handleDeleteUser = async (id) => {
    try {
      const token = localStorage.getItem('token'); // Obtener el token del localStorage

      if (!token) {
        console.error('Token no proporcionado');
        return; // Si no hay token, no hacemos la solicitud
      }

      const response = await fetch(`http://localhost:4000/api/user/${id}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      if (response.ok) {
        // Si la solicitud fue exitosa, actualizamos el estado
        setUsers(users.filter(user => user.id !== id));
        console.log('Usuario eliminado');
      } else {
        console.error('Error al eliminar el usuario:', response.statusText);
      }
    } catch (error) {
      console.error('Error al eliminar el usuario:', error);
    }
  };


  const handleView = (user) => {
    setSelectedUser(user);
    setEditMode(false);
  };

  const handleEdit = (user) => {
    setSelectedUser({ ...user });
    setEditMode(true);
  };

  const handleSave = () => {
    setUsers(users.map(u => (u.id === selectedUser.id ? selectedUser : u)));
    setSelectedUser(null);
  };

  const closeModal = () => {
    setSelectedUser(null);
    setEditMode(false);
  };

  return (
    <div className="usuarios-container">
      <h1>Gestión de Usuarios</h1>

      <div className="search-bar">
        <input
          type="text"
          placeholder="Buscar por nombre, apellido o email..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <button>🔍</button>
      </div>

      <table className="user-table">
        <thead>
          <tr>
            <th>Nombre</th>
            <th>Apellido</th>
            <th>Email</th>
            <th>Rol</th>
            <th>Acciones</th>
          </tr>
        </thead>
        <tbody>
          {filteredUsers.map(user => (
            <tr key={user.id}>
              <td>{user.nombre}</td>
              <td>{user.apellido}</td>
              <td>{user.email}</td>
              <td>{user.role}</td>
              <td>
                <button onClick={() => handleView(user)}>Ver</button>
                <button onClick={() => handleEdit(user)}>Modificar</button>
                <button onClick={() => handleDeleteUser(user.id)}>Dar de baja</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {selectedUser && (
        <div className="modal-overlay">
          <div className="modal">
            <span className="close" onClick={closeModal}>&times;</span>
            <h2>{editMode ? 'Modificar Usuario' : 'Información del Usuario'}</h2>
            <form onSubmit={(e) => { e.preventDefault(); handleSave(); }}>
              <label>Nombre:</label>
              <input
                type="text"
                value={selectedUser.nombre}
                onChange={(e) => setSelectedUser({ ...selectedUser, nombre: e.target.value })}
                disabled={!editMode}
              />
              <label>Apellido:</label>
              <input
                type="text"
                value={selectedUser.apellido}
                onChange={(e) => setSelectedUser({ ...selectedUser, apellido: e.target.value })}
                disabled={!editMode}
              />
              <label>Email:</label>
              <input
                type="email"
                value={selectedUser.email}
                onChange={(e) => setSelectedUser({ ...selectedUser, email: e.target.value })}
                disabled={!editMode}
              />
              <label>Rol:</label>
              <select
                value={selectedUser.role}
                onChange={(e) => setSelectedUser({ ...selectedUser, role: e.target.value })}
                disabled={!editMode}
              >
                <option value="usuario">usuario</option>
                <option value="administrador">administrador</option>
              </select>
              {editMode && <button type="submit" className="save-btn">Guardar</button>}
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default Usuarios;
